class Fill(object):
    """Fill specifies a value to use when the target is missing or None.

    If the target data matches certain "missing" criteria (e.g., None,
    empty collections), the fill value will be used instead. This is
    useful for providing defaults without needing explicit Coalesce calls.

    Args:
       spec: The specification to apply to the target
       fill_value: The value to use as a replacement for missing/empty data
       on_empty: Whether to also fill empty collections (default True)
       on_none: Whether to also fill None values (default True)

    >>> target = {'a': None}
    >>> glom(target, Fill('a', 'default'))
    'default'
    >>> target = {'a': [1, 2, 3]}
    >>> glom(target, Fill('a', []))
    [1, 2, 3]
    """
    def __init__(self, spec, fill_value, on_empty=True, on_none=True):
        self.spec = spec
        self.fill_value = fill_value
        self.on_empty = on_empty
        self.on_none = on_none

    def glomit(self, target, scope):
        val = scope[glom](target, self.spec, scope)
        if val is None and self.on_none:
            return self.fill_value
        if self.on_empty and hasattr(val, '__len__') and len(val) == 0:
            return self.fill_value
        return val

    def __repr__(self):
        cn = self.__class__.__name__
        args = ['spec=%r' % self.spec, 'fill_value=%r' % self.fill_value]
        if not self.on_empty:
            args.append('on_empty=%r' % self.on_empty)
        if not self.on_none:
            args.append('on_none=%r' % self.on_none)
        return '%s(%s)' % (cn, ', '.join(args))


class Auto(object):
    """Auto automatically selects the best way to process a spec based on
    the type of input it receives.

    When applied, Auto will inspect the input and choose appropriate
    processing - for example, treating strings as paths, dicts as
    dict specs, etc.

    Args:
       spec: The specification to apply auto-processing to

    >>> target = {'a': {'b': 'c'}}
    >>> glom(target, Auto('a.b'))
    'c'
    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        # For Auto, we just evaluate the spec normally
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        return 'Auto(%r)' % self.spec


class Iter(object):
    """Iter iterates over a spec, applying it to each element of an iterable.

    Similar to using a list comprehension but works within glom's
    specification system.

    Args:
       spec: The specification to apply to each item in the iterable

    >>> target = [{'a': 1}, {'a': 2}]
    >>> glom(target, Iter('a'))
    [1, 2]
    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        try:
            iterator = iterate(target)
        except Exception as e:
            raise TypeError('failed to iterate on instance of type %r at %r (got %r)'
                            % (target.__class__.__name__, Path(*scope[Path]), e))
        ret = []
        for i, t in enumerate(iterator):
            val = scope[glom](t, self.spec, scope.new_child({Path: scope[Path] + [i]}))
            if val is SKIP:
                continue
            if val is STOP:
                break
            ret.append(val)
        return ret

    def __repr__(self):
        return 'Iter(%r)' % self.spec


class Let(object):
    """Let binds names in a local scope for use by subsequent specs.

    Allows you to define intermediate variables that can be referenced
    later in the specification.

    Args:
       bindings: Dict mapping names to their values/specifications

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Let({'total': ('a', 'b'), 'double': T * 2}))
    {'total': 3, 'double': 4}
    """
    def __init__(self, bindings):
        self.bindings = bindings

    def glomit(self, target, scope):
        new_scope = scope.new_child()
        for name, spec in self.bindings.items():
            new_scope[name] = scope[glom](target, spec, scope)
        return new_scope

    def __repr__(self):
        return 'Let(%r)' % self.bindings


ROOT = make_sentinel('ROOT')
ROOT.__doc__ = """The ``ROOT`` singleton references the root target in nested
gloms. It can be used in :attr:`~glom.S` expressions to refer back to the
original data being processed.

>>> target = {'users': [{'name': 'Alice'}, {'name': 'Bob'}]}
>>> glom(target, [('name', S[ROOT]['users'][0]['name'])])
"""


class Invoke(object):
    """Invoke calls an object (typically a callable) with arguments derived
    from the target.

    Similar to Call but designed specifically for invoking objects that
    may not be simple callables, including methods, classes, etc.

    Args:
       obj: The object to invoke
       args: Positional arguments (can include T expressions)
       kwargs: Keyword arguments (can include T expressions)

    >>> class Example:
    ...     def method(self, x):
    ...         return x * 2
    >>> target = {'obj': Example()}
    >>> glom(target, Invoke(T['obj'].method, args=(5,)))
    10
    """
    def __init__(self, obj, args=None, kwargs=None):
        self.obj = obj
        if args is None:
            args = ()
        if kwargs is None:
            kwargs = {}
        self.args = args
        self.kwargs = kwargs

    def glomit(self, target, scope):
        def _eval(t):
            if isinstance(t, (Spec, TType)):
                return scope[glom](target, t, scope)
            return t
        evaluated_args = [_eval(a) for a in self.args]
        evaluated_kwargs = {k: _eval(v) for k, v in self.kwargs.items()}
        obj = scope[glom](target, self.obj, scope) if isinstance(self.obj, (Spec, TType)) else self.obj
        return obj(*evaluated_args, **evaluated_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        args_repr = ', '.join([
            'obj=%r' % self.obj,
            'args=%r' % self.args,
            'kwargs=%r' % self.kwargs,
        ])
        return '%s(%s)' % (cn, args_repr)


